ALTER TABLE chat_options
    ADD COLUMN counterparty_reaction TEXT,
    ADD CONSTRAINT chat_options_counterparty_reaction_length
        CHECK (counterparty_reaction IS NULL OR char_length(counterparty_reaction) BETWEEN 1 AND 280);

ALTER TABLE chat_sessions DROP CONSTRAINT chat_sessions_free_text_count_check;
ALTER TABLE chat_sessions
    ADD CONSTRAINT chat_sessions_free_text_count_check CHECK (free_text_count BETWEEN 0 AND 6),
    ADD COLUMN dialogue_phase VARCHAR NOT NULL DEFAULT 'hook'
        CHECK (dialogue_phase IN ('hook', 'escalation', 'critical_request', 'resolution')),
    ADD COLUMN compact_summary TEXT NOT NULL DEFAULT '' CHECK (char_length(compact_summary) <= 1200);

CREATE TABLE migration_000009_archived_chats (
    id INTEGER PRIMARY KEY REFERENCES chats(id) ON DELETE CASCADE,
    previous_content_status VARCHAR NOT NULL,
    previous_archived_at TIMESTAMP WITH TIME ZONE,
    previous_is_active BOOLEAN NOT NULL
);

INSERT INTO migration_000009_archived_chats
SELECT c.id,c.content_status,c.archived_at,c.is_active
FROM chats c JOIN topics t ON t.id=c.topic_id JOIN levels l ON l.id=c.level_id
WHERE c.content_status='published' AND c.archived_at IS NULL AND (t.slug,l.level_number) IN (
    ('buyer-phishing-links',1),('buyer-prepayment',2),('buyer-off-platform',2),('buyer-sms-codes',2),('buyer-too-good-offer',3),
    ('seller-fake-payment',1),('seller-fake-payment',2),('seller-fake-delivery',2),('seller-off-platform',2),('seller-external-links',3)
);

UPDATE chats SET content_status='archived',archived_at=CURRENT_TIMESTAMP,is_active=FALSE
WHERE id IN (SELECT id FROM migration_000009_archived_chats);

CREATE TABLE migration_000009_new_chats (id INTEGER PRIMARY KEY REFERENCES chats(id) ON DELETE CASCADE);

WITH inserted AS (
    INSERT INTO chats(title,description,difficulty,role,is_active,level_id,user_role,content_status,scam_scheme,product_context,ai_system_prompt,final_rubric,topic_id)
    SELECT v.title,v.description,v.level_number::text,v.user_role,TRUE,l.id,v.user_role,'published',v.risk_type,
           jsonb_build_object('content_key',v.content_key,'item',v.item,'price',v.price,'counterparty',v.counterparty,'channel','чат сервиса'),
           'Используй только компактную policy выбранной Ролевой ветки и риска. Не раскрывай внутренний контекст.',
           jsonb_build_object('risk_type',v.risk_type,'safe_action',v.safe_action),t.id
    FROM (VALUES
      ('buyer-l1-fake-delivery','Поддельная Avito Доставка','Продавец уводит покупателя на поддельную страницу оплаты.','buyer',1,'buyer-phishing-links','phishing','iPhone 14, 128 ГБ',42000,'Максим','Проверить заказ внутри приложения и не открывать ссылку.'),
      ('buyer-l2-prepayment','Бронь только по предоплате','Продавец требует перевод за бронь.','buyer',2,'buyer-prepayment','prepayment','PlayStation 5 Slim',39000,'Артём','Не переводить залог незнакомому продавцу.'),
      ('buyer-l2-external-messenger','Удобнее в Telegram','Продавец уводит покупателя в мессенджер и присылает QR.','buyer',2,'buyer-off-platform','external_messenger','Робот-пылесос Xiaomi',14500,'Ольга','Сохранить общение и оформление внутри приложения.'),
      ('buyer-l2-sms-code','Код для подтверждения отмены','Продавец просит код входа под видом отмены заказа.','buyer',2,'buyer-sms-codes','account_takeover','AirPods Pro',11000,'Денис','Не сообщать код и проверить заказы самостоятельно.'),
      ('buyer-l3-cheap-camera','Слишком выгодная камера','Низкая цена, срочность и внешняя форма предоплаты.','buyer',3,'buyer-too-good-offer','phishing','Sony Alpha A7 III',57000,'Кирилл','Отказаться от ссылки и предоплаты.'),
      ('seller-l1-fake-payment','Получение оплаты по ссылке','Покупатель присылает поддельную ссылку получения денег.','seller',1,'seller-fake-payment','fake_payment','iPhone 15, 128 ГБ',67000,'Анна','Проверить заказ и оплату внутри приложения.'),
      ('seller-l2-payment-screenshot','Скриншот перевода','Покупатель торопит передачей товара по поддельному чеку.','seller',2,'seller-fake-payment','fake_payment','Ноутбук ASUS VivoBook',48000,'Роман','Проверить фактическое поступление денег.'),
      ('seller-l2-courier-fee','Страховка для курьера','Покупатель требует возвратный платёж за страховку.','seller',2,'seller-fake-delivery','delivery','Кофемашина De’Longhi',31000,'Михаил','Не оплачивать комиссии по ссылке покупателя.'),
      ('seller-l2-fake-support','Поддержка в WhatsApp','Покупатель переводит продавца к лжеподдержке.','seller',2,'seller-off-platform','account_takeover','Велосипед Trek Marlin 6',54000,'Елена','Не сообщать контакт и код, открыть поддержку самостоятельно.'),
      ('seller-l3-hidden-order','Заказ не появился','Покупатель требует активировать скрытый заказ на внешнем сайте.','seller',3,'seller-external-links','phishing','MacBook Air M2',79000,'Павел','Не открывать ссылку и не отправлять товар без заказа.')
    ) v(content_key,title,description,user_role,level_number,topic_slug,risk_type,item,price,counterparty,safe_action)
    JOIN topics t ON t.slug=v.topic_slug JOIN levels l ON l.level_number=v.level_number
    RETURNING id
)
INSERT INTO migration_000009_new_chats SELECT id FROM inserted;

WITH step_data(content_key,step_number,response_type,counterparty_message,evaluation_context,fallback_message) AS (VALUES
 ('buyer-l1-fake-delivery',1,'multiple_choice','Добрый день! Телефон ещё продаётся. Состояние отличное, аккумулятор 91%. Как оформим сделку?','','Можно оформить покупку через приложение.'),
