INSERT INTO chat_steps(chat_id,step_number,response_type,step_goal,counterparty_message,ai_instruction,fallback_message,max_points)
SELECT c.id,d.step_number,d.response_type,'Выбрать безопасное действие в подготовленном Сценарии',d.counterparty_message,NULLIF(d.evaluation_context,''),d.fallback_message,100
FROM step_data d JOIN chats c ON c.product_context->>'content_key'=d.content_key
WHERE c.id IN (SELECT id FROM migration_000009_new_chats);

