INSERT INTO chat_options(step_id,option_text,counterparty_reaction,explanation,points,sort_order)
SELECT s.id,d.option_text,d.reaction,d.explanation,(ARRAY[0,25,75,100])[d.score],d.sort_order
FROM option_data d
JOIN chats c ON c.product_context->>'content_key'=d.content_key
JOIN chat_steps s ON s.chat_id=c.id AND s.step_number=d.step_number
WHERE c.id IN (SELECT id FROM migration_000009_new_chats);
